 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            pts = []
            while q:
                y, x = q.popleft()
                pts.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                            seen.add((ny, nx))
                            q.append((ny, nx))
            if len(pts) < 10:
                continue
            r0, r1 = min(y for y, x in pts), max(y for y, x in pts)
            c0, c1 = min(x for y, x in pts), max(x for y, x in pts)
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    out[y][x] = color
    return out
